-- Remaining 50 source messages. Run after 034. Existing messages are never overwritten.
begin;
lock table public.home_inspiration_messages in share row exclusive mode;
do $import$ declare wanted jsonb; incoming public.home_inspiration_messages%rowtype; current_row public.home_inspiration_messages%rowtype;
begin
for wanted in select value from jsonb_array_elements($records$[{"message_id": "INS_CONF_002", "message_text": "You can handle one decision at a time.", "theme": "CONFIDENCE", "message_type": "DAILY_GENERAL", "trigger_key": null, "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "INS_CONF_003", "message_text": "Confidence can grow from practice, not perfection.", "theme": "CONFIDENCE", "message_type": "DAILY_GENERAL", "trigger_key": null, "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "INS_CONF_004", "message_text": "You don't have to know every answer to ask a good question.", "theme": "CONFIDENCE", "message_type": "DAILY_GENERAL", "trigger_key": null, "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "INS_CONF_005", "message_text": "Notice what you already know how to do.", "theme": "CONFIDENCE", "message_type": "DAILY_GENERAL", "trigger_key": null, "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "INS_CONF_006", "message_text": "Trying something new counts, even when it feels awkward.", "theme": "CONFIDENCE", "message_type": "DAILY_GENERAL", "trigger_key": null, "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "INS_CONF_007", "message_text": "You can learn your way through unfamiliar situations.", "theme": "CONFIDENCE", "message_type": "DAILY_GENERAL", "trigger_key": null, "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "INS_CONF_008", "message_text": "Your voice gets stronger each time you use it.", "theme": "CONFIDENCE", "message_type": "DAILY_GENERAL", "trigger_key": null, "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "INS_STEP_002", "message_text": "You don't have to solve the whole week today.", "theme": "SMALL_STEPS", "message_type": "DAILY_GENERAL", "trigger_key": null, "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "INS_STEP_003", "message_text": "A five-minute plan can be enough to get started.", "theme": "SMALL_STEPS", "message_type": "DAILY_GENERAL", "trigger_key": null, "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "INS_STEP_004", "message_text": "Do the next useful thing. The rest can wait.", "theme": "SMALL_STEPS", "message_type": "DAILY_GENERAL", "trigger_key": null, "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "INS_STEP_005", "message_text": "Small choices can make a busy day feel more manageable.", "theme": "SMALL_STEPS", "message_type": "DAILY_GENERAL", "trigger_key": null, "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "INS_STEP_006", "message_text": "Progress can look quiet: one question, one plan, one choice.", "theme": "SMALL_STEPS", "message_type": "DAILY_GENERAL", "trigger_key": null, "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "INS_STEP_007", "message_text": "You can make this easier by breaking it into pieces.", "theme": "SMALL_STEPS", "message_type": "DAILY_GENERAL", "trigger_key": null, "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "INS_STEP_008", "message_text": "A little preparation can create more room for everything else.", "theme": "SMALL_STEPS", "message_type": "DAILY_GENERAL", "trigger_key": null, "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "INS_TRUST_002", "message_text": "It's okay to need more information before you decide.", "theme": "SELF_TRUST", "message_type": "DAILY_GENERAL", "trigger_key": null, "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "INS_TRUST_003", "message_text": "You are allowed to change your mind when you learn something new.", "theme": "SELF_TRUST", "message_type": "DAILY_GENERAL", "trigger_key": null, "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "INS_TRUST_004", "message_text": "You don't have to copy someone else's choice.", "theme": "SELF_TRUST", "message_type": "DAILY_GENERAL", "trigger_key": null, "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "INS_TRUST_005", "message_text": "You can listen to advice and still make your own decision.", "theme": "SELF_TRUST", "message_type": "DAILY_GENERAL", "trigger_key": null, "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "INS_TRUST_006", "message_text": "Not sure yet is a valid place to start.", "theme": "SELF_TRUST", "message_type": "DAILY_GENERAL", "trigger_key": null, "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "INS_TRUST_007", "message_text": "You get to decide what information you need to feel comfortable.", "theme": "SELF_TRUST", "message_type": "DAILY_GENERAL", "trigger_key": null, "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "INS_TRUST_008", "message_text": "Trust can take time. You don't have to rush it.", "theme": "SELF_TRUST", "message_type": "DAILY_GENERAL", "trigger_key": null, "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "INS_CONN_002", "message_text": "Asking for support is a skill, not a setback.", "theme": "CONNECTION", "message_type": "DAILY_GENERAL", "trigger_key": null, "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "INS_CONN_003", "message_text": "Being independent doesn't mean doing everything alone.", "theme": "CONNECTION", "message_type": "DAILY_GENERAL", "trigger_key": null, "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "INS_CONN_004", "message_text": "The right people will want to know how to include you.", "theme": "CONNECTION", "message_type": "DAILY_GENERAL", "trigger_key": null, "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "INS_CONN_005", "message_text": "You can let someone help and still stay in charge of your choices.", "theme": "CONNECTION", "message_type": "DAILY_GENERAL", "trigger_key": null, "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "INS_CONN_006", "message_text": "A good plan can include other people.", "theme": "CONNECTION", "message_type": "DAILY_GENERAL", "trigger_key": null, "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "INS_CONN_007", "message_text": "You don't have to explain everything to be included.", "theme": "CONNECTION", "message_type": "DAILY_GENERAL", "trigger_key": null, "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "INS_CONN_008", "message_text": "Connection matters, even when food isn't the focus.", "theme": "CONNECTION", "message_type": "DAILY_GENERAL", "trigger_key": null, "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "INS_FLEX_002", "message_text": "A backup plan isn't a failure. It's another option.", "theme": "FLEXIBILITY", "message_type": "DAILY_GENERAL", "trigger_key": null, "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "INS_FLEX_003", "message_text": "There can be more than one good way through a situation.", "theme": "FLEXIBILITY", "message_type": "DAILY_GENERAL", "trigger_key": null, "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "INS_FLEX_004", "message_text": "You can prepare without planning every detail.", "theme": "FLEXIBILITY", "message_type": "DAILY_GENERAL", "trigger_key": null, "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "INS_FLEX_005", "message_text": "If something changes, you can change the plan too.", "theme": "FLEXIBILITY", "message_type": "DAILY_GENERAL", "trigger_key": null, "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "INS_FLEX_006", "message_text": "Sometimes the best plan is the simplest one.", "theme": "FLEXIBILITY", "message_type": "DAILY_GENERAL", "trigger_key": null, "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "INS_FLEX_007", "message_text": "You can make a new choice when the situation changes.", "theme": "FLEXIBILITY", "message_type": "DAILY_GENERAL", "trigger_key": null, "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "INS_FLEX_008", "message_text": "Flexibility means having options, not lowering your standards.", "theme": "FLEXIBILITY", "message_type": "DAILY_GENERAL", "trigger_key": null, "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "INS_LIFE_002", "message_text": "Today can be about something you love.", "theme": "LIFE_BEYOND_CELIAC", "message_type": "DAILY_GENERAL", "trigger_key": null, "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "INS_LIFE_003", "message_text": "Food is one part of the plan. Being there matters too.", "theme": "LIFE_BEYOND_CELIAC", "message_type": "DAILY_GENERAL", "trigger_key": null, "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "INS_LIFE_004", "message_text": "You are more than the things you have to manage.", "theme": "LIFE_BEYOND_CELIAC", "message_type": "DAILY_GENERAL", "trigger_key": null, "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "INS_LIFE_005", "message_text": "Make room for the part of the day you're actually excited about.", "theme": "LIFE_BEYOND_CELIAC", "message_type": "DAILY_GENERAL", "trigger_key": null, "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "INS_LIFE_006", "message_text": "A safe plan is there to support your life, not take it over.", "theme": "LIFE_BEYOND_CELIAC", "message_type": "DAILY_GENERAL", "trigger_key": null, "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "INS_LIFE_007", "message_text": "You can care for yourself and still focus on the fun.", "theme": "LIFE_BEYOND_CELIAC", "message_type": "DAILY_GENERAL", "trigger_key": null, "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "INS_LIFE_008", "message_text": "Some days, doing less celiac thinking is a win.", "theme": "LIFE_BEYOND_CELIAC", "message_type": "DAILY_GENERAL", "trigger_key": null, "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "CTX_UPCOMING_002", "message_text": "You don't need a perfect plan. You need a plan that works for you.", "theme": "FLEXIBILITY", "message_type": "CONTEXTUAL", "trigger_key": "UPCOMING_CDAY", "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "CTX_HARD_DONE_002", "message_text": "That took effort. You showed up for it.", "theme": "CONFIDENCE", "message_type": "CONTEXTUAL", "trigger_key": "HARD_ACTION_DONE", "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "CTX_RESCHEDULE_002", "message_text": "Rescheduling is still planning.", "theme": "FLEXIBILITY", "message_type": "CONTEXTUAL", "trigger_key": "ACTION_RESCHEDULED", "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "CTX_NOT_NEEDED_001", "message_text": "You noticed what you needed and adjusted. That counts.", "theme": "SELF_TRUST", "message_type": "CONTEXTUAL", "trigger_key": "ACTION_NOT_NEEDED", "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "CTX_EXPLORE_001", "message_text": "Learning one useful thing is enough for today.", "theme": "SMALL_STEPS", "message_type": "CONTEXTUAL", "trigger_key": "EXPLORE_COMPLETED", "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "CTX_NO_EVENT_002", "message_text": "No planning needed right now. Enjoy the space.", "theme": "LIFE_BEYOND_CELIAC", "message_type": "CONTEXTUAL", "trigger_key": "NO_UPCOMING_CDAY", "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "CTX_PLAN_FINAL_001", "message_text": "Your plan is ready. Now you can get back to your day.", "theme": "LIFE_BEYOND_CELIAC", "message_type": "CONTEXTUAL", "trigger_key": "PLAN_FINALIZED", "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}, {"message_id": "CTX_SUPPORT_001", "message_text": "Letting someone help can be part of being independent.", "theme": "CONNECTION", "message_type": "CONTEXTUAL", "trigger_key": "SUPPORT_USED", "source_basis": ["American Academy of Pediatrics / HealthyChildren.org", "UNICEF Adolescent Mental Health Hub", "CDC adolescent connectedness guidance", "Stanford Medicine Children's Celiac Disease Program"], "review_status": "approved", "expert_reviewed": false, "active": true, "content_version": "1.0"}]$records$::jsonb) loop
 select * into incoming from jsonb_populate_record(null::public.home_inspiration_messages,wanted);
 select * into current_row from public.home_inspiration_messages where message_id=incoming.message_id;
 if found then
  if exists(select 1 from jsonb_each(wanted) f where to_jsonb(current_row)->f.key is distinct from f.value) then raise exception 'Message % differs; no changes made.',incoming.message_id;end if;
 else
 insert into public.home_inspiration_messages(message_id,message_text,theme,message_type,trigger_key,source_basis,review_status,expert_reviewed,active,content_version) values (incoming.message_id,incoming.message_text,incoming.theme,incoming.message_type,incoming.trigger_key,incoming.source_basis,incoming.review_status,incoming.expert_reviewed,incoming.active,incoming.content_version);
 end if;
end loop;
end $import$;
